package com.gymflex.service;
import com.gymflex.entity.*; import com.gymflex.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class GymService { private final MemberRepository mr; private final PlanRepository pr; private final MembershipRepository memr; private final CheckInRepository cr; public GymService(MemberRepository mr,PlanRepository pr,MembershipRepository memr,CheckInRepository cr){this.mr=mr;this.pr=pr;this.memr=memr;this.cr=cr;}
@Transactional public Member register(Member m,Long pid){if(mr.findByPhone(m.getPhone()).isPresent())throw new IllegalArgumentException("Phone number already registered."); Plan p=pr.findById(pid).orElseThrow(()->new IllegalArgumentException("Plan not found."));m.setPlan(p);Member s=mr.save(m);Membership x=new Membership();x.setMember(s);x.setPlan(p);x.setStartDate(LocalDate.now());x.setEndDate(LocalDate.now().plusMonths(p.getMonths()));memr.save(x);return s;}
@Transactional public Membership renew(Long id,Long pid){Member m=get(id);Plan p=pr.findById(pid).orElseThrow(()->new IllegalArgumentException("Plan not found."));Membership x=membership(id);LocalDate base=x.getEndDate().isAfter(LocalDate.now())?x.getEndDate():LocalDate.now();x.setPlan(p);x.setStartDate(base);x.setEndDate(base.plusMonths(p.getMonths()));m.setPlan(p);mr.save(m);return memr.save(x);}
@Transactional public CheckIn checkIn(Long id){Member m=get(id);Membership x=membership(id);LocalDate d=LocalDate.now();if(x.getEndDate().isBefore(d))throw new IllegalArgumentException("Check-in rejected: membership has expired.");if(cr.existsByMemberIdAndCheckInDate(id,d))throw new IllegalArgumentException("Already checked in today.");CheckIn c=new CheckIn();c.setMember(m);c.setCheckInDate(d);c.setCheckInTime(LocalDateTime.now());return cr.save(c);}
public Member get(Long id){return mr.findById(id).orElseThrow(()->new IllegalArgumentException("Member not found."));} public Membership membership(Long id){return memr.findByMemberId(id).orElseThrow(()->new IllegalArgumentException("Membership not found."));} public List<Member> members(){return mr.findAll();} public List<Plan> plans(){return pr.findAll();} public List<Membership> expiring(){LocalDate d=LocalDate.now();return memr.findByEndDateBetween(d,d.plusDays(7));} public int attendance(Long id){LocalDate d=LocalDate.now();return cr.findByMemberIdAndCheckInDateBetween(id,d.withDayOfMonth(1),d).size();} public long memberCount(){return mr.count();} public long checkInCount(){return cr.count();} }